"""Sixth curated tranche of materially distinct Python algorithms."""

ADVANCED_TASK_CODE_SPECS_6 = (
    ("union_find_queries", "Write a Python function that processes union and connectivity-query operations over numbered elements using disjoint sets with path compression and union by size.", "def process_connectivity_queries(size, operations):\n    if size < 0:\n        raise ValueError(\"size must be nonnegative\")\n    parent = list(range(size))\n    component_size = [1] * size\n    def find(node):\n        while parent[node] != node:\n            parent[node] = parent[parent[node]]\n            node = parent[node]\n        return node\n    answers = []\n    for operation, left, right in operations:\n        if not (0 <= left < size and 0 <= right < size):\n            raise ValueError(\"element out of range\")\n        left_root, right_root = find(left), find(right)\n        if operation == \"union\":\n            if left_root != right_root:\n                if component_size[left_root] < component_size[right_root]:\n                    left_root, right_root = right_root, left_root\n                parent[right_root] = left_root\n                component_size[left_root] += component_size[right_root]\n        elif operation == \"connected\":\n            answers.append(left_root == right_root)\n        else:\n            raise ValueError(\"unknown operation\")\n    return answers"),
    ("lowest_common_ancestors", "Write a Python function that answers lowest-common-ancestor queries in a rooted tree using binary lifting and rejects nodes not reachable from the root.", "def lowest_common_ancestors(graph, root, queries):\n    parent = {root: root}\n    depth = {root: 0}\n    queue = [root]\n    for node in queue:\n        for child in graph.get(node, []):\n            if child not in parent:\n                parent[child] = node\n                depth[child] = depth[node] + 1\n                queue.append(child)\n    levels = max(1, len(parent).bit_length())\n    jump = [parent]\n    for _ in range(1, levels):\n        previous = jump[-1]\n        jump.append({node: previous[previous[node]] for node in parent})\n    answers = []\n    for left, right in queries:\n        if left not in parent or right not in parent:\n            raise ValueError(\"query node is outside the rooted tree\")\n        if depth[left] < depth[right]:\n            left, right = right, left\n        difference = depth[left] - depth[right]\n        for bit in range(levels):\n            if difference & (1 << bit):\n                left = jump[bit][left]\n        if left == right:\n            answers.append(left)\n            continue\n        for bit in range(levels - 1, -1, -1):\n            if jump[bit][left] != jump[bit][right]:\n                left, right = jump[bit][left], jump[bit][right]\n        answers.append(parent[left])\n    return answers"),
    ("binary_tree_serialization", "Write a Python function that round-trips a binary tree represented by nested three-item tuples through a preorder token stream with explicit null markers.", "def round_trip_binary_tree(tree):\n    tokens = []\n    def encode(node):\n        if node is None:\n            tokens.append(None)\n            return\n        if not isinstance(node, tuple) or len(node) != 3:\n            raise ValueError(\"nodes must be (value, left, right) tuples\")\n        tokens.append(node[0])\n        encode(node[1])\n        encode(node[2])\n    encode(tree)\n    position = 0\n    def decode():\n        nonlocal position\n        if position >= len(tokens):\n            raise ValueError(\"truncated token stream\")\n        value = tokens[position]\n        position += 1\n        if value is None:\n            return None\n        return (value, decode(), decode())\n    restored = decode()\n    if position != len(tokens):\n        raise ValueError(\"unused tokens\")\n    return tokens, restored"),
    ("k_way_merge", "Write a Python function that merges any number of sorted sequences into one sorted list using a manually maintained minimum heap and stable source ordering.", "def merge_many_sorted(sequences):\n    heap = []\n    result = []\n    def push(item):\n        heap.append(item)\n        index = len(heap) - 1\n        while index:\n            parent = (index - 1) // 2\n            if heap[parent] <= heap[index]:\n                break\n            heap[parent], heap[index] = heap[index], heap[parent]\n            index = parent\n    for source, sequence in enumerate(sequences):\n        if sequence:\n            push((sequence[0], source, 0))\n    while heap:\n        value, source, offset = heap[0]\n        result.append(value)\n        replacement_offset = offset + 1\n        if replacement_offset < len(sequences[source]):\n            heap[0] = (sequences[source][replacement_offset], source, replacement_offset)\n        else:\n            heap[0] = heap[-1]\n            heap.pop()\n        index = 0\n        while index * 2 + 1 < len(heap):\n            child = index * 2 + 1\n            if child + 1 < len(heap) and heap[child + 1] < heap[child]:\n                child += 1\n            if heap[index] <= heap[child]:\n                break\n            heap[index], heap[child] = heap[child], heap[index]\n            index = child\n    return result"),
    ("aho_corasick_matches", "Write a Python function that returns all pattern occurrences in text using an Aho-Corasick trie with failure links, including overlapping matches.", "def multi_pattern_match_indices(text, patterns):\n    transitions = [{}]\n    failure = [0]\n    outputs = [[]]\n    for pattern_index, pattern in enumerate(patterns):\n        if not pattern:\n            raise ValueError(\"patterns must be non-empty\")\n        state = 0\n        for character in pattern:\n            if character not in transitions[state]:\n                transitions[state][character] = len(transitions)\n                transitions.append({})\n                failure.append(0)\n                outputs.append([])\n            state = transitions[state][character]\n        outputs[state].append(pattern_index)\n    queue = list(transitions[0].values())\n    for state in queue:\n        for character, target in transitions[state].items():\n            fallback = failure[state]\n            while fallback and character not in transitions[fallback]:\n                fallback = failure[fallback]\n            failure[target] = transitions[fallback].get(character, 0)\n            outputs[target].extend(outputs[failure[target]])\n            queue.append(target)\n    matches = []\n    state = 0\n    for end, character in enumerate(text):\n        while state and character not in transitions[state]:\n            state = failure[state]\n        state = transitions[state].get(character, 0)\n        for pattern_index in outputs[state]:\n            matches.append((pattern_index, end - len(patterns[pattern_index]) + 1))\n    return matches"),
    ("modular_power", "Write a Python function that computes a nonnegative integer exponent modulo a positive modulus using repeated squaring.", "def modular_power(base, exponent, modulus):\n    if exponent < 0 or modulus <= 0:\n        raise ValueError(\"exponent must be nonnegative and modulus positive\")\n    result = 1 % modulus\n    base %= modulus\n    while exponent:\n        if exponent & 1:\n            result = result * base % modulus\n        base = base * base % modulus\n        exponent //= 2\n    return result"),
    ("extended_gcd", "Write a Python function that returns the greatest common divisor of two integers and Bezout coefficients using the iterative extended Euclidean algorithm.", "def extended_greatest_common_divisor(left, right):\n    old_remainder, remainder = abs(left), abs(right)\n    old_left, current_left = 1, 0\n    old_right, current_right = 0, 1\n    while remainder:\n        quotient = old_remainder // remainder\n        old_remainder, remainder = remainder, old_remainder - quotient * remainder\n        old_left, current_left = current_left, old_left - quotient * current_left\n        old_right, current_right = current_right, old_right - quotient * current_right\n    return old_remainder, old_left if left >= 0 else -old_left, old_right if right >= 0 else -old_right"),
    ("chinese_remainder", "Write a Python function that solves pairwise-coprime congruences using constructive inverses and returns the least nonnegative solution with the combined modulus.", "def solve_coprime_congruences(remainders, moduli):\n    if len(remainders) != len(moduli) or not moduli:\n        raise ValueError(\"remainders and moduli must be non-empty and aligned\")\n    combined = 1\n    for modulus in moduli:\n        if modulus <= 0:\n            raise ValueError(\"moduli must be positive\")\n        combined *= modulus\n    result = 0\n    for remainder, modulus in zip(remainders, moduli):\n        partial = combined // modulus\n        old_remainder, current_remainder = partial, modulus\n        old_coefficient, current_coefficient = 1, 0\n        while current_remainder:\n            quotient = old_remainder // current_remainder\n            old_remainder, current_remainder = current_remainder, old_remainder - quotient * current_remainder\n            old_coefficient, current_coefficient = current_coefficient, old_coefficient - quotient * current_coefficient\n        if old_remainder != 1:\n            raise ValueError(\"moduli must be pairwise coprime\")\n        result += remainder * old_coefficient * partial\n    return result % combined, combined"),
    ("pascal_triangle_row", "Write a Python function that returns a requested zero-indexed row of Pascal's triangle by updating coefficients multiplicatively with exact integer division.", "def pascal_triangle_row(index):\n    if index < 0:\n        raise ValueError(\"index must be nonnegative\")\n    row = [1]\n    value = 1\n    for column in range(1, index + 1):\n        value = value * (index - column + 1) // column\n        row.append(value)\n    return row"),
    ("gray_code_sequence", "Write a Python function that returns the reflected binary Gray-code sequence for a nonnegative bit width as fixed-width strings.", "def reflected_gray_codes(width):\n    if width < 0:\n        raise ValueError(\"width must be nonnegative\")\n    if width == 0:\n        return [\"\"]\n    return [format(value ^ (value >> 1), f\"0{width}b\") for value in range(1 << width)]"),
    ("next_permutation", "Write a Python function that returns the next lexicographic permutation of a sequence as a new list, or None when the input is already last.", "def next_lexicographic_permutation(values):\n    result = list(values)\n    pivot = len(result) - 2\n    while pivot >= 0 and result[pivot] >= result[pivot + 1]:\n        pivot -= 1\n    if pivot < 0:\n        return None\n    successor = len(result) - 1\n    while result[successor] <= result[pivot]:\n        successor -= 1\n    result[pivot], result[successor] = result[successor], result[pivot]\n    result[pivot + 1:] = reversed(result[pivot + 1:])\n    return result"),
    ("josephus_survivor", "Write a Python function that returns the zero-based surviving position in the Josephus elimination process for positive population and step sizes.", "def josephus_surviving_position(population, step):\n    if population <= 0 or step <= 0:\n        raise ValueError(\"population and step must be positive\")\n    survivor = 0\n    for size in range(2, population + 1):\n        survivor = (survivor + step) % size\n    return survivor"),
    ("n_queens_solutions", "Write a Python function that returns every placement of nonattacking queens on an n-by-n board as tuples of column indices, ordered by row.", "def solve_n_queens(size):\n    if size < 0:\n        raise ValueError(\"size must be nonnegative\")\n    solutions = []\n    columns = set()\n    rising = set()\n    falling = set()\n    placement = []\n    def place(row):\n        if row == size:\n            solutions.append(tuple(placement))\n            return\n        for column in range(size):\n            if column in columns or row + column in rising or row - column in falling:\n                continue\n            columns.add(column)\n            rising.add(row + column)\n            falling.add(row - column)\n            placement.append(column)\n            place(row + 1)\n            placement.pop()\n            falling.remove(row - column)\n            rising.remove(row + column)\n            columns.remove(column)\n    place(0)\n    return solutions"),
    ("sudoku_solver", "Write a Python function that solves a nine-by-nine Sudoku grid containing zeroes for blanks by backtracking with row, column, and box constraints, without mutating the input.", "def solve_sudoku(grid):\n    if len(grid) != 9 or any(len(row) != 9 for row in grid):\n        raise ValueError(\"grid must be nine by nine\")\n    board = [list(row) for row in grid]\n    rows = [set() for _ in range(9)]\n    columns = [set() for _ in range(9)]\n    boxes = [set() for _ in range(9)]\n    blanks = []\n    for row in range(9):\n        for column in range(9):\n            value = board[row][column]\n            if value == 0:\n                blanks.append((row, column))\n                continue\n            box = row // 3 * 3 + column // 3\n            if value not in range(1, 10) or value in rows[row] or value in columns[column] or value in boxes[box]:\n                raise ValueError(\"invalid grid\")\n            rows[row].add(value)\n            columns[column].add(value)\n            boxes[box].add(value)\n    def fill(position):\n        if position == len(blanks):\n            return True\n        best = min(range(position, len(blanks)), key=lambda index: len(set(range(1, 10)) - rows[blanks[index][0]] - columns[blanks[index][1]] - boxes[blanks[index][0] // 3 * 3 + blanks[index][1] // 3]))\n        blanks[position], blanks[best] = blanks[best], blanks[position]\n        row, column = blanks[position]\n        box = row // 3 * 3 + column // 3\n        for value in sorted(set(range(1, 10)) - rows[row] - columns[column] - boxes[box]):\n            board[row][column] = value\n            rows[row].add(value); columns[column].add(value); boxes[box].add(value)\n            if fill(position + 1):\n                return True\n            rows[row].remove(value); columns[column].remove(value); boxes[box].remove(value)\n        board[row][column] = 0\n        blanks[position], blanks[best] = blanks[best], blanks[position]\n        return False\n    if not fill(0):\n        return None\n    return board"),
    ("stable_matching", "Write a Python function that computes a stable one-to-one matching from two complete preference dictionaries using proposer-optimal deferred acceptance.", "def stable_preference_matching(proposer_preferences, receiver_preferences):\n    proposers = set(proposer_preferences)\n    receivers = set(receiver_preferences)\n    if any(set(order) != receivers for order in proposer_preferences.values()) or any(set(order) != proposers for order in receiver_preferences.values()):\n        raise ValueError(\"preferences must be complete\")\n    ranks = {receiver: {proposer: rank for rank, proposer in enumerate(order)} for receiver, order in receiver_preferences.items()}\n    next_choice = {proposer: 0 for proposer in proposers}\n    free = list(proposers)\n    held = {}\n    while free:\n        proposer = free.pop()\n        order = proposer_preferences[proposer]\n        if next_choice[proposer] == len(order):\n            raise ValueError(\"no complete matching exists\")\n        receiver = order[next_choice[proposer]]\n        next_choice[proposer] += 1\n        current = held.get(receiver)\n        if current is None or ranks[receiver][proposer] < ranks[receiver][current]:\n            held[receiver] = proposer\n            if current is not None:\n                free.append(current)\n        else:\n            free.append(proposer)\n    return {proposer: receiver for receiver, proposer in held.items()}"),
    ("bipartite_maximum_matching", "Write a Python function that returns a maximum matching from left-side nodes to right-side nodes in a bipartite adjacency dictionary using augmenting paths.", "def maximum_bipartite_matching(graph):\n    right_match = {}\n    def augment(left, seen):\n        for right in graph.get(left, []):\n            if right in seen:\n                continue\n            seen.add(right)\n            if right not in right_match or augment(right_match[right], seen):\n                right_match[right] = left\n                return True\n        return False\n    for left in graph:\n        augment(left, set())\n    return {left: right for right, left in right_match.items()}"),
    ("interval_stabbing_points", "Write a Python function that returns a minimum-size sorted set of points intersecting every closed interval by greedily selecting right endpoints.", "def minimum_interval_stabbing_points(intervals):\n    ordered = []\n    for start, end in intervals:\n        if start > end:\n            raise ValueError(\"interval start exceeds end\")\n        ordered.append((end, start))\n    points = []\n    for end, start in sorted(ordered):\n        if not points or points[-1] < start:\n            points.append(end)\n    return points"),
    ("graph_k_core", "Write a Python function that returns the vertices in the k-core of an undirected adjacency dictionary by repeatedly removing vertices below the degree threshold.", "def graph_k_core_vertices(graph, threshold):\n    if threshold < 0:\n        raise ValueError(\"threshold must be nonnegative\")\n    nodes = set(graph)\n    for neighbors in graph.values():\n        nodes.update(neighbors)\n    neighbors = {node: set(graph.get(node, [])) & nodes for node in nodes}\n    active = set(nodes)\n    queue = [node for node in active if len(neighbors[node]) < threshold]\n    position = 0\n    while position < len(queue):\n        node = queue[position]\n        position += 1\n        if node not in active:\n            continue\n        active.remove(node)\n        for neighbor in neighbors[node] & active:\n            neighbors[neighbor].discard(node)\n            if len(neighbors[neighbor] & active) < threshold:\n                queue.append(neighbor)\n    return active"),
    ("page_rank", "Write a Python function that computes a fixed number of PageRank iterations for a directed adjacency dictionary, redistributing dangling-node mass uniformly.", "def iterative_page_rank(graph, iterations, damping=0.85):\n    if iterations < 0 or not 0 <= damping <= 1:\n        raise ValueError(\"invalid iteration count or damping\")\n    nodes = set(graph)\n    for targets in graph.values():\n        nodes.update(targets)\n    if not nodes:\n        return {}\n    count = len(nodes)\n    rank = {node: 1 / count for node in nodes}\n    for _ in range(iterations):\n        dangling = sum(rank[node] for node in nodes if not graph.get(node))\n        updated = {node: (1 - damping) / count + damping * dangling / count for node in nodes}\n        for source in nodes:\n            targets = graph.get(source, [])\n            if targets:\n                share = damping * rank[source] / len(targets)\n                for target in targets:\n                    updated[target] += share\n        rank = updated\n    return rank"),
    ("game_of_life_step", "Write a Python function that computes one Conway's Game of Life step for a rectangular zero-one grid without mutating it.", "def game_of_life_step(grid):\n    if not grid:\n        return []\n    columns = len(grid[0])\n    if any(len(row) != columns for row in grid) or any(value not in (0, 1) for row in grid for value in row):\n        raise ValueError(\"grid must be rectangular and binary\")\n    result = [[0] * columns for _ in grid]\n    for row in range(len(grid)):\n        for column in range(columns):\n            neighbors = 0\n            for row_delta in (-1, 0, 1):\n                for column_delta in (-1, 0, 1):\n                    if row_delta == column_delta == 0:\n                        continue\n                    next_row, next_column = row + row_delta, column + column_delta\n                    if 0 <= next_row < len(grid) and 0 <= next_column < columns:\n                        neighbors += grid[next_row][next_column]\n            result[row][column] = int(neighbors == 3 or grid[row][column] == 1 and neighbors == 2)\n    return result"),
    ("takeaway_game_strategy", "Write a Python function that determines whether the first player can force a win in a finite subtraction game and returns one winning opening move when available.", "def subtraction_game_opening(total, moves):\n    if total < 0 or not moves or any(move <= 0 for move in moves):\n        raise ValueError(\"total must be nonnegative and moves positive\")\n    allowed = sorted(set(moves))\n    winning = [False] * (total + 1)\n    choice = [None] * (total + 1)\n    for stones in range(1, total + 1):\n        for move in allowed:\n            if move > stones:\n                break\n            if not winning[stones - move]:\n                winning[stones] = True\n                choice[stones] = move\n                break\n    return winning[total], choice[total]"),
    ("polynomial_division", "Write a Python function that divides one polynomial by another using descending-power coefficient lists and returns quotient and remainder without mutating either input.", "def divide_polynomials(dividend, divisor):\n    if not divisor or all(coefficient == 0 for coefficient in divisor):\n        raise ValueError(\"divisor must be nonzero\")\n    numerator = list(dividend)\n    while numerator and numerator[0] == 0:\n        numerator.pop(0)\n    denominator = list(divisor)\n    while denominator and denominator[0] == 0:\n        denominator.pop(0)\n    if len(numerator) < len(denominator):\n        return [0], numerator or [0]\n    quotient = [0] * (len(numerator) - len(denominator) + 1)\n    for offset in range(len(quotient)):\n        factor = numerator[offset] / denominator[0]\n        quotient[offset] = factor\n        for index, coefficient in enumerate(denominator):\n            numerator[offset + index] -= factor * coefficient\n    remainder = numerator[len(quotient):]\n    while len(remainder) > 1 and remainder[0] == 0:\n        remainder.pop(0)\n    return quotient, remainder or [0]"),
    ("trapezoidal_integral", "Write a Python function that estimates the integral of tabulated values at strictly increasing coordinates using the composite trapezoidal rule.", "def trapezoidal_integral(coordinates, values):\n    if len(coordinates) != len(values) or len(coordinates) < 2:\n        raise ValueError(\"coordinates and values must align and contain at least two points\")\n    total = 0\n    for index in range(1, len(coordinates)):\n        width = coordinates[index] - coordinates[index - 1]\n        if width <= 0:\n            raise ValueError(\"coordinates must be strictly increasing\")\n        total += width * (values[index - 1] + values[index]) / 2\n    return total"),
    ("tridiagonal_system", "Write a Python function that solves a nonsingular tridiagonal linear system from its three diagonals using the Thomas algorithm on copied values.", "def solve_tridiagonal_system(lower, diagonal, upper, values):\n    size = len(diagonal)\n    if len(values) != size or len(lower) != max(0, size - 1) or len(upper) != max(0, size - 1):\n        raise ValueError(\"diagonal lengths do not align\")\n    if size == 0:\n        return []\n    pivots = list(diagonal)\n    result = list(values)\n    for index in range(1, size):\n        if pivots[index - 1] == 0:\n            raise ValueError(\"zero pivot\")\n        factor = lower[index - 1] / pivots[index - 1]\n        pivots[index] -= factor * upper[index - 1]\n        result[index] -= factor * result[index - 1]\n    if pivots[-1] == 0:\n        raise ValueError(\"zero pivot\")\n    solution = [0] * size\n    solution[-1] = result[-1] / pivots[-1]\n    for index in range(size - 2, -1, -1):\n        if pivots[index] == 0:\n            raise ValueError(\"zero pivot\")\n        solution[index] = (result[index] - upper[index] * solution[index + 1]) / pivots[index]\n    return solution"),
)
